INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Beschaffungsmanagement > Nutzwertanalysen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen bei einer Nutzwertanalyse immer mehrere Kriterien berücksichtigt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Mehrere Kriterien sind Grundlage der Bewertung"}, {"text": "Nein", "correct": false, "because": "Einzelkriterium unzureichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Nutzwertanalyse ohne Gewichtung der Kriterien durchgeführt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Gewichtung ist essenziell für die Priorisierung"}, {"text": "Ja", "correct": false, "because": "Ohne Gewichtung unspezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Nutzwertanalyse ein objektives Verfahren?', 2, '[{"text": "Nein", "correct": true, "because": "Subjektive Gewichtung beeinflusst Ergebnisse"}, {"text": "Ja", "correct": false, "because": "Subjektivität vorhanden"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Nutzwertanalysen auch qualitative Kriterien bewerten?', 2, '[{"text": "Ja", "correct": true, "because": "Qualitative Aspekte werden in Punkte umgewandelt"}, {"text": "Nein", "correct": false, "because": "Qualitativ bewertbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Nutzwertanalyse nur für die Lieferantenauswahl relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Produkte und Dienstleistungen nutzbar"}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Schritt ist bei der Nutzwertanalyse am wichtigsten?', 3, '[{"text": "Kriteriengewichtung", "correct": true, "because": "Bestimmt Prioritäten"}, {"text": "Farbauswahl", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Ein Kriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Nutzwertanalyse primär?', 2, '[{"text": "Optimale Entscheidungsfindung", "correct": true, "because": "Bewertet Alternativen"}, {"text": "Kostensenkung", "correct": false, "because": "Indirekt"}, {"text": "Schnelle Auswahl", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium wird in der Nutzwertanalyse typischerweise bewertet?', 2, '[{"text": "Kosten", "correct": true, "because": "Häufiges Bewertungskriterium"}, {"text": "Farbe", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeitpunkt", "correct": false, "because": "Ein Kriterium"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wird zur Bewertung in der Nutzwertanalyse verwendet?', 3, '[{"text": "Punktesystem", "correct": true, "because": "Kriterien werden in Punkte umgewandelt"}, {"text": "Zufallsauswahl", "correct": false, "because": "Nicht systematisch"}, {"text": "Kostenrechnung", "correct": false, "because": "Andere Methode"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil der Nutzwertanalyse?', 2, '[{"text": "Transparente Entscheidung", "correct": true, "because": "Nachvollziehbare Bewertung"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Zeitaufwendig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Schritte gehören zur Nutzwertanalyse?', 4, '[{"text": "Kriterien festlegen", "correct": true, "because": "Grundlage der Bewertung"}, {"text": "Gewichtung bestimmen", "correct": true, "because": "Priorisiert Kriterien"}, {"text": "Bewertung durchführen", "correct": true, "because": "Punktevergabe"}, {"text": "Farben auswählen", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien können in einer Nutzwertanalyse bewertet werden?', 3, '[{"text": "Kosten", "correct": true, "because": "Wirtschaftlicher Faktor"}, {"text": "Qualität", "correct": true, "because": "Produktmerkmal"}, {"text": "Lieferzeit", "correct": true, "because": "Logistischer Aspekt"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Nutzwertanalyse?', 3, '[{"text": "Transparenz", "correct": true, "because": "Klarheit im Prozess"}, {"text": "Vergleichbarkeit", "correct": true, "because": "Alternativen bewertbar"}, {"text": "Entscheidungsunterstützung", "correct": true, "because": "Hilft bei Auswahl"}, {"text": "Minimale Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Nutzwertanalyse auftreten?', 4, '[{"text": "Subjektivität", "correct": true, "because": "Gewichtung kann variieren"}, {"text": "Unvollständige Kriterien", "correct": true, "because": "Verzerrt Ergebnisse"}, {"text": "Komplexität", "correct": true, "because": "Zeitaufwendig"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für eine erfolgreiche Nutzwertanalyse wichtig?', 3, '[{"text": "Relevante Kriterien", "correct": true, "because": "Sichern Aussagekraft"}, {"text": "Objektive Bewertung", "correct": true, "because": "Reduziert Subjektivität"}, {"text": "Gewichtungsfaktoren", "correct": true, "because": "Bestimmen Prioritäten"}, {"text": "Produktfarbe", "correct": false, "because": "Ästhetisch"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Nutzwertanalyse verwendet ein Punktesystem. b) Kriteriengewichtung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Punkte ja, Gewichtung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kosten sind ein typisches Kriterium in der Nutzwertanalyse. b) Die Analyse ist vollständig objektiv.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten ja, Subjektivität vorhanden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Qualitative Kriterien können in der Nutzwertanalyse bewertet werden. b) Sie ist nur für Lieferanten relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualitativ ja, breiter einsetzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Nutzwertanalyse unterstützt die Entscheidungsfindung. b) Mehrere Kriterien sind optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Entscheidung ja, Kriterien nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Transparenz ist ein Vorteil der Nutzwertanalyse. b) Subjektivität kann die Ergebnisse verzerren.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Transparenz und Subjektivität korrekt"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides richtig"}]');

